const isReal=u=> !!(u&& !isDemoUser(u)&& !u.isAdmin&&ROLES.includes(u.type)&& /@/.test(String(u.email||'')));
const realAs=type=>{const u=me();return isReal(u)&&u.type===type?u:null;};
const own=u=>(u?String(u.dataKey||u.email||''):'');
