function pid(teenKey,jobId){
let h=2166136261;const s=teenKey+'|'+jobId;
for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)>>>0;}
return 3e15+h*1000+(Number(String(jobId).slice(-3))||0);
}
