if(!isNaN(d)){const a=n.getFullYear()-d.getFullYear()-(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate())?1:0);return a>=10&&a<=17?a:null;}
